2: // The city simulation is an original, self-contained top-down game. It does not load GTA assets.
3: const game=document.getElementById('game'),canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mapC=document.getElementById('mapCanvas'),mctx=mapC.getContext('2d');
4: const W=2600,H=2000,roadX=[300,700,1100,1500,1900,2300],roadY=[250,600,950,1300,1650];let buildings=[],parks=[],packages=[{x:500,y:250,got:false},{x:1100,y:690,got:false},{x:1880,y:1300,got:false}];
5: let player={x:490,y:320,angle:0,money:2500,inCar:false,car:null},camera={x:0,y:0},keys={},joy={x:0,y:0},running=false,gameActive=false,playersCurrent=428,lastTime=0,npcs=[],cars=[],seenPackages=0;
6: const colors=['#96795b','#788067','#997455','#747963','#9b8865','#6a7c70','#8a7259'];
7: function setupCity(){buildings=[];parks=[];let xs=[0,360,760,1160,1560,1960,2360],ys=[0,310,660,1010,1360,1710,2000];for(let iy=0;iy<ys.length-1;iy++)for(let ix=0;ix<xs.length-1;ix++){let x=xs[ix]+19,y=ys[iy]+18,w=xs[ix+1]-xs[ix]-38,h=ys[iy+1]-ys[iy]-36;if(w<80||h<80)continue;let seed=(ix*23+iy*37)%11;if(seed===3||seed===8){parks.push({x,y,w,h,trees:Array.from({length:Math.max(3,Math.floor(w*h/15000))},(_,j)=>({x:x+20+((j*79+ix*41)%Math.max(30,w-40)),y:y+20+((j*57+iy*29)%Math.max(30,h-40)),r:9+(j%4)*2}))});continue}let count=w>300?2:1;for(let j=0;j<count;j++){let bw=count===2?(w-20)/2:w-12,bx=x+(count===2?j*(bw+8)+4:6),by=y+7,bh=h-14;if(count===1&&h>280){bh=h-35}buildings.push({x:bx,y:by,w:bw,h:bh,c:colors[(ix*3+iy*5+j)%colors.length],roof:(ix+iy+j)%3})}}
8:  cars=[{x:405,y:249,a:0,c:'#d7aa54',occupied:false},{x:710,y:375,a:Math.PI/2,c:'#83a3a0',occupied:false},{x:1040,y:599,a:0,c:'#b86655',occupied:false},{x:1500,y:740,a:Math.PI/2,c:'#d7d1b4',occupied:false},{x:1900,y:1120,a:Math.PI/2,c:'#8296bd',occupied:false},{x:2200,y:1299,a:0,c:'#abbd61',occupied:false}];
9:  npcs=Array.from({length:19},(_,i)=>({x:400+(i*137)%2100,y:270+(i*211)%1600,a:(i*1.7)%6.28,phase:i*3.1,color:['#e7b08b','#d9d4bb','#96b5a2','#cf8773'][i%4],speed:.2+(i%3)*.14}));}
10: setupCity();
