12: function connect(name){gameActive=true;document.getElementById('app').style.display='none';game.style.display='block';document.getElementById('gameServer').innerHTML=`${escapeHTML(name)}<small><i class="dot" style="display:inline-block;width:5px;height:5px;margin-right:3px"></i> SESSÃO DE DEMONSTRAÇÃO</small>`;let server=customServers.find(s=>s.name===name);playersCurrent=server?1:428;document.getElementById('playersHud').innerHTML=`${playersCurrent} <small style="font:8px var(--mono);color:#8f9d8e">/ ${server?.max||500}</small>`;requestAnimationFrame(loop);setTimeout(()=>gameMessage('Bem-vindo à cidade! Chegue perto de um pacote verde.'),400)}
