15: function addChat(name,text){let log=document.getElementById('chatLog'),line=document.createElement('div');line.className='chat-line';line.innerHTML=`<b>${escapeHTML(name)}:</b> ${escapeHTML(text)}`;log.appendChild(line);while(log.children.length>3)log.firstChild.remove();setTimeout(()=>line.remove(),6500)}
16: function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
17: function isBlocked(x,y,r=12){for(let b of buildings)if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true;return x<10||y<10||x>W-10||y>H-10}
18: function act(){if(!gameActive)return;let nearest=packages.find(p=>!p.got&&Math.hypot(p.x-player.x,p.y-player.y)<53);if(nearest){nearest.got=true;seenPackages++;player.money+=750;document.getElementById('cash').textContent='$ '+player.money.toLocaleString('pt-BR');document.getElementById('packageCount').textContent=`${seenPackages} / 3`;document.getElementById('progress').style.width=`${seenPackages/3*100}%`;gameMessage(seenPackages===3?'Trampo completo! +$ 750':'Pacote coletado! +$ 750');addChat('Central','Entrega registrada. Mandou bem!');if(seenPackages===3)setTimeout(()=>gameMessage('Missão concluída · seu próximo rolê é por sua conta.'),2200);return}
19:  if(player.inCar){player.inCar=false;player.car.occupied=false;player.x+=Math.cos(player.angle+Math.PI/2)*28;player.y+=Math.sin(player.angle+Math.PI/2)*28;player.car=null;gameMessage('Você saiu do veículo');return}
20:  let car=cars.find(c=>Math.hypot(c.x-player.x,c.y-player.y)<58&&!c.occupied);if(car){car.occupied=true;player.inCar=true;player.car=car;player.x=car.x;player.y=car.y;player.angle=car.a;gameMessage('Veículo emprestado. Bora dar uma volta!');addChat('Sistema','Você entrou em um veículo.');return}
